styl:
.b-iq-hero-34 u + .body .gmail-blend-screen {  background: #000;
  mix-blend-mode: screen;  }
.b-iq-hero-34 u + .body .gmail-blend-diff {  background: #000;
  mix-blend-mode: difference;  }
.bgr-image.b-iq-hero-34 {  background: url("https://fsms.quadcode.com/storage/public/d6/sm/6hrs2mcraq8anbt0/2-3-4-back.png") center top no-repeat;
  background-size: cover;
  background-color: #000;  }
.brad-full.b-iq-hero-34 {  border-radius: 32px !important;  }
.b-iq-hero-34 .white-title {  font-family: Helvetica !important;
  font-weight: 700;
  font-size: 34px;
  line-height: 46px;
  color: #f9f9f9;
  word-break: break-word;  }
@media screen and (max-width: 600px) {
  .b-iq-hero-34 .white-title {  font-size: 26px !important;
    line-height: 32px !important;  }
}
.b-iq-hero-34 .white-text {  font-family: Helvetica !important;
  font-style: normal;
  font-weight: 400;
  font-size: 18px;
  line-height: 27px;
  color: #fff;  }
@media screen and (max-width: 600px) {
  .b-iq-hero-34 .white-text {  padding-right: 0 !important;  }
}
.b-iq-hero-34 .pb16 {  padding-bottom: 16px;  }
.b-iq-hero-34 .h-406 {  font-size: 8px;
  line-height: 280px;
  height: 280px;  }
@media screen and (max-width: 600px) {
  .b-iq-hero-34 .h-406 {  line-height: 300px;
    height: 300px;  }
}
